    attacking:{att:.19,def:-.12,poss:-1,shots:1.5,discipline:.02},
    defensive:{att:-.18,def:.19,poss:-2,shots:-1.2,discipline:-.02},
    pressing:{att:.10,def:.08,poss:1,shots:.5,discipline:.10},
