      const minute=randInt(1,90);
      const quality=clamp(.055+(profile.att-70)*.0015+(profile.tech-70)*.001+(Math.random()*.16)+(tac.att*.045)-(opp.def-70)*.0008,.025,.42);
      const on=Math.random()<onRate;
