    homeRedCards:Math.random()<.025?1:0,awayRedCards:Math.random()<.025?1:0,
    homePassAccuracy:passHome,awayPassAccuracy:passAway,homeBigChances:hs.bigChances,awayBigChances:as.bigChances,
